#include <algorithm>
#include <format>
#include <iostream>
#include <vector>

class Listener {
 public:
  Listener() = default;
  Listener(const Listener&) = delete;
  Listener& operator=(const Listener&) = delete;
  virtual ~Listener() = default;
  virtual void on_event(int value) = 0;
};

class EventSource {
 public:
  void subscribe(Listener& listener) { listeners_.push_back(&listener); }
  void unsubscribe(Listener& listener) { std::erase(listeners_, &listener); }
  void notify(int value) {
    for (Listener* listener : listeners_) listener->on_event(value);
  }

 private:
  std::vector<Listener*> listeners_;
};

class PrintingListener final : public Listener {
 public:
  void on_event(int value) override { std::cout << std::format("saw {}\n", value); }
};

int main() {
  EventSource source;
  {
    PrintingListener listener;
    source.subscribe(listener);
    source.notify(1);
  }  // listener destroyed here, without unsubscribing first
  source.notify(2);  // calls into a destroyed object
}

