#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

struct Reading {
  std::int32_t temperature_c;
  std::int32_t humidity_pct;
};

// The target the subject calls: pushed the full reading, whether a listener needs all of it or not.
class WeatherListener {
 public:
  WeatherListener() = default;
  WeatherListener(const WeatherListener&) = delete;
  WeatherListener& operator=(const WeatherListener&) = delete;
  virtual ~WeatherListener() = default;
  virtual void on_reading(const Reading& reading) = 0;
};

class WeatherStation {
 public:
  void subscribe(WeatherListener& listener) { listeners_.push_back(&listener); }

  void publish(Reading reading) {
    for (WeatherListener* listener : listeners_) listener->on_reading(reading);
  }

 private:
  std::vector<WeatherListener*> listeners_;
};

class Logger final : public WeatherListener {
 public:
  void on_reading(const Reading& reading) override {
    std::cout << std::format("log: {} C, {}%\n", reading.temperature_c, reading.humidity_pct);
  }
};

// Only ever reads the temperature, and is still handed the humidity on every call.
class FrostAlarm final : public WeatherListener {
 public:
  void on_reading(const Reading& reading) override {
    if (reading.temperature_c <= 0) std::cout << std::format("frost alarm: {} C\n", reading.temperature_c);
  }
};

int main() {
  WeatherStation station;
  Logger logger;
  FrostAlarm alarm;
  station.subscribe(logger);
  station.subscribe(alarm);

  station.publish({.temperature_c = 8, .humidity_pct = 55});
  station.publish({.temperature_c = -2, .humidity_pct = 80});
}

#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

struct Reading {
  std::int32_t temperature_c;
  std::int32_t humidity_pct;
};

class WeatherListener {
 public:
  WeatherListener() = default;
  WeatherListener(const WeatherListener&) = delete;
  WeatherListener& operator=(const WeatherListener&) = delete;
  virtual ~WeatherListener() = default;
  virtual void on_changed() = 0;  // no data: the listener asks for what it needs
};

class WeatherStation {
 public:
  void subscribe(WeatherListener& listener) { listeners_.push_back(&listener); }

  void publish(Reading reading) {
    reading_ = reading;
    for (WeatherListener* listener : listeners_) listener->on_changed();
  }

  [[nodiscard]] const Reading& reading() const { return reading_; }

 private:
  std::vector<WeatherListener*> listeners_;
  Reading reading_{};
};

// Reads only the field it cares about, by calling back into the station.
class FrostAlarm final : public WeatherListener {
 public:
  explicit FrostAlarm(const WeatherStation& station) : station_(station) {}
  void on_changed() override {
    if (station_.reading().temperature_c <= 0) {
      std::cout << std::format("frost alarm: {} C\n", station_.reading().temperature_c);
    }
  }

 private:
  const WeatherStation& station_;
};

int main() {
  WeatherStation station;
  FrostAlarm alarm(station);
  station.subscribe(alarm);

  station.publish({.temperature_c = 8, .humidity_pct = 55});
  station.publish({.temperature_c = -2, .humidity_pct = 80});
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <utility>
#include <vector>

struct Token {
  std::int64_t id;
};
[[nodiscard]] constexpr bool operator==(Token a, Token b) { return a.id == b.id; }

template <typename... Args>
class EventSource {
 public:
  using Callback = std::function<void(Args...)>;

  [[nodiscard]] Token subscribe(Callback callback) {
    const Token token{.id = next_id_++};
    callbacks_.emplace_back(token, std::move(callback));
    return token;
  }

  void unsubscribe(Token token) {
    std::erase_if(callbacks_, [token](const auto& entry) { return entry.first == token; });
  }

  void notify(Args... args) const {
    for (const auto& [token, callback] : callbacks_) callback(args...);
  }

  [[nodiscard]] std::size_t listener_count() const { return callbacks_.size(); }

 private:
  std::vector<std::pair<Token, Callback>> callbacks_;
  std::int64_t next_id_ = 0;
};

int main() {
  EventSource<std::int32_t> voltage_mv;

  const Token logger = voltage_mv.subscribe([](std::int32_t mv) { std::cout << std::format("log: {} mV\n", mv); });
  const Token alarm = voltage_mv.subscribe([](std::int32_t mv) {
    if (mv < 11000) std::cout << std::format("low battery alarm: {} mV\n", mv);
  });

  std::cout << std::format("listeners: {}\n", voltage_mv.listener_count());
  voltage_mv.notify(12400);
  voltage_mv.notify(10800);

  voltage_mv.unsubscribe(alarm);
  std::cout << std::format("listeners after unsubscribe: {}\n", voltage_mv.listener_count());
  voltage_mv.notify(9000);  // no alarm printed: it was unsubscribed

  voltage_mv.unsubscribe(logger);
  std::cout << std::format("listeners after both unsubscribed: {}\n", voltage_mv.listener_count());
}

