 public:
  using Callback = std::function<void(Args...)>;
  [[nodiscard]] Token subscribe(Callback callback) {
    const Token token{.id = next_id_++};
    callbacks_.emplace_back(token, std::move(callback));
    return token;
  }
  void notify(Args... args) const {
    for (const auto& [token, callback] : callbacks_) callback(args...);
  }

 private:
  std::vector<std::pair<Token, Callback>> callbacks_;
  std::int64_t next_id_ = 0;
};

class VoltageLogger {
 public:
  // Keeps the token, but nothing ever calls source.unsubscribe(token_) with it.
  explicit VoltageLogger(EventSource<std::int32_t>& source) {
    token_ = source.subscribe([this](std::int32_t mv) { log(mv); });
  }
  void log(std::int32_t mv) {
    ++seen_;
    std::cout << std::format("log #{}: {} mV\n", seen_, mv) << std::flush;  // visible before the crash below
  }

 private:
  Token token_{};
  int seen_ = 0;
};

int main() {
  EventSource<std::int32_t> voltage_mv;
  {
    VoltageLogger logger(voltage_mv);
    voltage_mv.notify(12000);
  }  // logger destroyed here, without unsubscribing
  voltage_mv.notify(9000);  // the stored lambda still calls into it
}

