#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

struct Token {
  std::int64_t id;
};
[[nodiscard]] constexpr bool operator==(Token a, Token b) { return a.id == b.id; }

template <typename... Args>
class EventSource {
 public:
  using Callback = std::function<void(Args...)>;
  [[nodiscard]] Token subscribe(Callback callback) {
    const Token token{.id = next_id_++};
    callbacks_.emplace_back(token, std::move(callback));
    return token;
  }
  void unsubscribe(Token token) {
    std::erase_if(callbacks_, [token](const auto& entry) { return entry.first == token; });
  }
  void notify(Args... args) const {
    for (const auto& [token, callback] : callbacks_) callback(args...);
  }

 private:
  std::vector<std::pair<Token, Callback>> callbacks_;
  std::int64_t next_id_ = 0;
};

int main() {
  EventSource<int> source;
  [[maybe_unused]] const Token before =
      source.subscribe([](int mv) { std::cout << std::format("before saw {}\n", mv); });

  const std::string tag = "self-unsubscribing listener";  // captured by value, lives inside the closure
  Token self_token{};
  self_token = source.subscribe([&source, &self_token, tag](int mv) {
    source.unsubscribe(self_token);                        // destroys this closure, tag included
    std::cout << std::format("{} saw {}\n", tag, mv);       // reads tag after it is gone
  });

  source.notify(1);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <mutex>
#include <utility>
#include <vector>

struct Token {
  std::int64_t id;
};
[[nodiscard]] constexpr bool operator==(Token a, Token b) { return a.id == b.id; }

// Guarded the way cpp-threads-mutexes guards any data several threads reach: one mutex, next to it.
template <typename... Args>
class EventSource {
 public:
  using Callback = std::function<void(Args...)>;

  [[nodiscard]] Token subscribe(Callback callback) {
    const std::lock_guard<std::mutex> lock(mutex_);
    const Token token{.id = next_id_++};
    callbacks_.emplace_back(token, std::move(callback));
    return token;
  }
  void unsubscribe(Token token) {
    const std::lock_guard<std::mutex> lock(mutex_);
    std::erase_if(callbacks_, [token](const auto& entry) { return entry.first == token; });
  }
  void notify(Args... args) {
    const std::lock_guard<std::mutex> lock(mutex_);
    for (const auto& [token, callback] : callbacks_) callback(args...);
  }

 private:
  mutable std::mutex mutex_;
  std::vector<std::pair<Token, Callback>> callbacks_;
  std::int64_t next_id_ = 0;
};

int main() {
  EventSource<std::int32_t> voltage_mv;
  [[maybe_unused]] const Token token =
      voltage_mv.subscribe([](std::int32_t mv) { std::cout << std::format("log: {} mV\n", mv); });
  voltage_mv.notify(12000);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <vector>

class VoltageListener {
 public:
  VoltageListener() = default;
  VoltageListener(const VoltageListener&) = delete;
  VoltageListener& operator=(const VoltageListener&) = delete;
  virtual ~VoltageListener() = default;
  virtual void on_reading(std::int32_t mv) = 0;
};

// Holds weak_ptrs: a destroyed listener is skipped, never dereferenced.
class VoltageSource {
 public:
  void subscribe(std::weak_ptr<VoltageListener> listener) { listeners_.push_back(std::move(listener)); }

  void notify(std::int32_t mv) {
    for (const std::weak_ptr<VoltageListener>& weak : listeners_) {
      if (const std::shared_ptr<VoltageListener> alive = weak.lock()) alive->on_reading(mv);
    }
    // Safe to erase now: the loop above has already finished.
    std::erase_if(listeners_, [](const std::weak_ptr<VoltageListener>& weak) { return weak.expired(); });
  }

  [[nodiscard]] std::size_t listener_count() const { return listeners_.size(); }

 private:
  std::vector<std::weak_ptr<VoltageListener>> listeners_;
};

class Logger final : public VoltageListener {
 public:
  void on_reading(std::int32_t mv) override { std::cout << std::format("log: {} mV\n", mv); }
};

int main() {
  VoltageSource source;
  auto logger = std::make_shared<Logger>();
  source.subscribe(logger);

  {
    auto temporary = std::make_shared<Logger>();
    source.subscribe(temporary);
    std::cout << std::format("listeners before it goes out of scope: {}\n", source.listener_count());
    source.notify(12000);
  }  // temporary destroyed here; source still holds a weak_ptr to it, not a dangling raw pointer

  source.notify(9000);  // the expired weak_ptr is skipped, not dereferenced
  std::cout << std::format("listeners after the next notify pruned it: {}\n", source.listener_count());
}
